import{_ as a,o as i,c as s,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const k=JSON.parse('{"title":"Outbox Pattern","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/queue/outbox.md","filePath":"system-design/queue/outbox.md","lastUpdated":1788475713000}'),n={name:"system-design/queue/outbox.md"};function o(r,e,l,p,d,c){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="outbox-pattern" tabindex="-1">Outbox Pattern <a class="header-anchor" href="#outbox-pattern" aria-label="Permalink to &quot;Outbox Pattern&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>服务做两件事: (1) 更新数据库, (2) 发消息队列. 但是<strong>两件事跨进程 atomic 不可能——没有 in-process 两阶段 commit</strong>（即让 DB commit 与外部 message queue send 在同一原子单元同步）。 如果 DB 先 commit + queue send 失败, downstream 永远没消息; 如果 queue 先 send + DB fail, downstream 看到消息但 DB 未更新。 都是数据不一致。</p><p><strong>Outbox Pattern</strong>: 业务 transaction 内 → 同事务 insert outbox table → DB commit 后异步 worker poll outbox table 把 events send 到 queue + mark as sent。 &quot;Outbox 表与业务表在同一 DB transaction → 它们 atomic&quot;. 单 service 内 consistency + 跨 service availability 解耦。</p><hr><h2 id="一、pattern" tabindex="-1">一、Pattern <a class="header-anchor" href="#一、pattern" aria-label="Permalink to &quot;一、Pattern&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用 transfer(from_id, to_id, amt, event_id):</span></span>
<span class="line"><span>    # begin DB transaction</span></span>
<span class="line"><span>    UPDATE accounts SET balance = balance - \${amt} WHERE id = \${from_id};</span></span>
<span class="line"><span>    UPDATE accounts SET balance = balance + \${amt} WHERE id = \${to_id};</span></span>
<span class="line"><span>    INSERT INTO outbox (event_id, event_type, payload)</span></span>
<span class="line"><span>        VALUES (\${event_id}, &quot;Transfer&quot;, {...});</span></span>
<span class="line"><span>    # commit (atomic)</span></span></code></pre></div><p>后台 worker:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loop:</span></span>
<span class="line"><span>    rows = SELECT * FROM outbox WHERE sent_at IS NULL LIMIT 1000;</span></span>
<span class="line"><span>    for row in rows:</span></span>
<span class="line"><span>        try:</span></span>
<span class="line"><span>            queue.send(topic, row.payload, idempotency_key=row.event_id)</span></span>
<span class="line"><span>            UPDATE outbox SET sent_at = now() WHERE event_id = row.event_id;</span></span>
<span class="line"><span>            COMMIT;</span></span>
<span class="line"><span>        except:</span></span>
<span class="line"><span>            backoff() retry</span></span></code></pre></div><p>外部效果:</p><ul><li>不丢失 (DB 与 outbox 同事务 atomic)</li><li>不重复 (queue 发送 idempotent — idempotency_key 防重复 send)</li><li>至少一次 (worker 持续 poll 直到 success)</li></ul><hr><h2 id="二、cdc-change-data-capture-变体" tabindex="-1">二、CDC (Change Data Capture) 变体 <a class="header-anchor" href="#二、cdc-change-data-capture-变体" aria-label="Permalink to &quot;二、CDC (Change Data Capture) 变体&quot;">​</a></h2><p>经典 outbox 用 application-level background worker poll outbox table. 现代 push-based CDC 用 DB transaction log 监听实时事件流。</p><h3 id="debezium" tabindex="-1">Debezium <a class="header-anchor" href="#debezium" aria-label="Permalink to &quot;Debezium&quot;">​</a></h3><ul><li>实时监听 PostgreSQL WAL / MySQL binlog / MongoDB oplog, 写入 Kafka Connect</li><li>应用只需写业务表 + outbox 表; Debezium 自动把 outbox row 变成 Kafka event</li><li>满足 lower latency + better robust</li></ul><h3 id="pros-vs-manual-worker" tabindex="-1">Pros vs manual worker <a class="header-anchor" href="#pros-vs-manual-worker" aria-label="Permalink to &quot;Pros vs manual worker&quot;">​</a></h3><ul><li><strong>No application code changes</strong>: worker 不在 application 中, CDC engine 自动处理</li><li><strong>Lower latency</strong>: binlog tail 实时, 比 poll 接近实时</li><li><strong>Robust</strong>: binlog replay from any LSN 恢复避免丢; worker crash 不丢 job</li></ul><h3 id="cons" tabindex="-1">Cons <a class="header-anchor" href="#cons" aria-label="Permalink to &quot;Cons&quot;">​</a></h3><ul><li>依赖 Debezium platform (Kafka Connect 部署 + 维护成本)</li><li>复杂事务 log (binlog interpretation 需要理解 row + 关系)</li><li>coupling with DB engine: WAL / binlog format changes with版本, Debezium 需跟随升级</li></ul><h3 id="kafka-connect-dlq" tabindex="-1">Kafka Connect DLQ <a class="header-anchor" href="#kafka-connect-dlq" aria-label="Permalink to &quot;Kafka Connect DLQ&quot;">​</a></h3><p>CDC source connector 配置 <code>errors.deadletterqueue.topic.name</code> 后 CDC failures 上 DLQ topic, 让 DLQ monitor/根 analysis。</p><hr><h2 id="三、at-least-once-worker" tabindex="-1">三、At-Least-Once Worker <a class="header-anchor" href="#三、at-least-once-worker" aria-label="Permalink to &quot;三、At-Least-Once Worker&quot;">​</a></h2><p>Worker 必须 strict + idempotent.</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">loop polling:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    rows </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> event_id, payload </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> outbox</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> false</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           FOR</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> UPDATE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SKIP</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LOCKED</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">;</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">    --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PostgreSQL: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FOR</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> UPDATE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SKIP</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LOCKED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 让多 workers 并发处理不同 row</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    foreach row </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rows:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            queue.send(topic, payload, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">row.event_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        except</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Exception</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            log(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;queue down, retry later&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">            continue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 不标 sent=true, 下次 iter 再发</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> outbox </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> event_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> row.event_id</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        COMMIT</span></span></code></pre></div><p><code>FOR UPDATE SKIP LOCKED</code> 是 PostgreSQL 9.5+ 并发 select pattern 让多 worker concurrent grab 不同 rows. MySQL 8.0+ 同; Oracle 与 SQL Server 也有 equivalent (<code>READPAST</code>)。</p><hr><h2 id="四、idempotency-key-ordering" tabindex="-1">四、Idempotency Key + Ordering <a class="header-anchor" href="#四、idempotency-key-ordering" aria-label="Permalink to &quot;四、Idempotency Key + Ordering&quot;">​</a></h2><p>发送 ID 等业务 event_id, queue 端去重:</p><ul><li>Kafka 通过 <code>producer_id</code> 提供 produce-side sequence dedup, application-level event_id 是更业务级的 idempotency key</li><li>发送时用 event_id 作为 partition key 路由 Kafka partition: 同一 entity (e.g. user_id) 的 events 全落同 partition → Kafka ordering within partition 保</li><li>同 entity 必 serial (用户 account transaction 序)</li></ul><p>跨多 partitions 排序不 保证. 若业务需要全序则单 partition 限制 throughput.</p><hr><h2 id="五、常见-5-种-worker" tabindex="-1">五、常见 5 种 worker <a class="header-anchor" href="#五、常见-5-种-worker" aria-label="Permalink to &quot;五、常见 5 种 worker&quot;">​</a></h2><h3 id="_1-in-process-background-thread-simple" tabindex="-1">1. In-process background thread (simple) <a class="header-anchor" href="#_1-in-process-background-thread-simple" aria-label="Permalink to &quot;1. In-process background thread (simple)&quot;">​</a></h3><ul><li>同 server 程序内一个 worker 定时 poll outbox</li><li>弱点: 重启 server 时 worker停 ～</li></ul><h3 id="_2-独立-worker-pool-high-availability-microservice" tabindex="-1">2. 独立 worker pool (high availability microservice) <a class="header-anchor" href="#_2-独立-worker-pool-high-availability-microservice" aria-label="Permalink to &quot;2. 独立 worker pool (high availability microservice)&quot;">​</a></h3><ul><li>deploy 单独服务 worker pool 并发消费 outbox</li><li>每个 Pod 用 <code>SKIP LOCKED</code> 抢 work item</li><li>限 worker 数 = max DB connection (e.g. 10 connections)</li></ul><h3 id="_3-cdc-debezium-kafka-connect" tabindex="-1">3. CDC (Debezium / Kafka Connect) <a class="header-anchor" href="#_3-cdc-debezium-kafka-connect" aria-label="Permalink to &quot;3. CDC (Debezium / Kafka Connect)&quot;">​</a></h3><ul><li>独立服务 attach DB binlog → emit Kafka topic</li><li>满足 lower latency + better robust</li><li>external deploy</li></ul><h3 id="_4-cloud-platform-eventbridge-sqs-lambda" tabindex="-1">4. Cloud platform: EventBridge / SQS / Lambda <a class="header-anchor" href="#_4-cloud-platform-eventbridge-sqs-lambda" aria-label="Permalink to &quot;4. Cloud platform: EventBridge / SQS / Lambda&quot;">​</a></h3><ul><li>AWS Lambda 定时 poll outbox 自动 send 到 EventBridge / SQS</li><li>原生 cloud support with failover</li></ul><h3 id="_5-multi-instance-consistency" tabindex="-1">5. Multi-instance + consistency <a class="header-anchor" href="#_5-multi-instance-consistency" aria-label="Permalink to &quot;5. Multi-instance + consistency&quot;">​</a></h3><ul><li>partition by entity_id 让同 entity processed serially; but multi instances 仍并行 between entities</li><li>复制 worker into partitioned jobs with consistent hashing for backlog entities</li></ul><hr><h2 id="六、典型使用例" tabindex="-1">六、典型使用例 <a class="header-anchor" href="#六、典型使用例" aria-label="Permalink to &quot;六、典型使用例&quot;">​</a></h2><h3 id="order-service-shipping-service" tabindex="-1">Order Service -&gt; Shipping Service <a class="header-anchor" href="#order-service-shipping-service" aria-label="Permalink to &quot;Order Service -&gt; Shipping Service&quot;">​</a></h3><p>订单 service 创建 order commit; outbox row emit &quot;OrderCreated&quot; event; Shipping service consumes + 创建 shipping record. Idempotent on order_id.</p><h3 id="user-account-email-service" tabindex="-1">User Account -&gt; Email Service <a class="header-anchor" href="#user-account-email-service" aria-label="Permalink to &quot;User Account -&gt; Email Service&quot;">​</a></h3><p>User signup commit; outbox row emit &quot;WelcomeEmail&quot; event; email service consumes. Idempotent on user_id + skip duplicates.</p><h3 id="twitter-tweet-created-followers-fanout" tabindex="-1">Twitter Tweet Created -&gt; Followers Fanout <a class="header-anchor" href="#twitter-tweet-created-followers-fanout" aria-label="Permalink to &quot;Twitter Tweet Created -&gt; Followers Fanout&quot;">​</a></h3><p>Tweet service commit; outbox row &quot;TweetCreated&quot; event; Fanout service consumes 推到 followers&#39; timeline cache. Idempotency on tweet_id; partition by author_id for ordering.</p><h3 id="stripe-webhook-billing-update" tabindex="-1">Stripe Webhook -&gt; Billing Update <a class="header-anchor" href="#stripe-webhook-billing-update" aria-label="Permalink to &quot;Stripe Webhook -&gt; Billing Update&quot;">​</a></h3><p>Stripe sends webhook to customer billing system. Billing system insert outbox &quot;Stripe.Event.WebhookReceived&quot; event → 后台 worker persist state, detect idempotency via Stripe event_id + skip duplicates.</p><h3 id="paypal-payment-fraud-detection-service" tabindex="-1">Paypal Payment -&gt; Fraud Detection Service <a class="header-anchor" href="#paypal-payment-fraud-detection-service" aria-label="Permalink to &quot;Paypal Payment -&gt; Fraud Detection Service&quot;">​</a></h3><p>在 PayPal commit + outbox event; fraud detection 仅 idempotency (after analysis 避双 score revert).</p><hr><h2 id="七、典型事故" tabindex="-1">七、典型事故 <a class="header-anchor" href="#七、典型事故" aria-label="Permalink to &quot;七、典型事故&quot;">​</a></h2><h3 id="worker-crash-messages-lost" tabindex="-1">Worker crash, messages lost <a class="header-anchor" href="#worker-crash-messages-lost" aria-label="Permalink to &quot;Worker crash, messages lost&quot;">​</a></h3><p>某公司 worker thread embedded in app process; deployed new build → container kill worker mid send with outbox row marked unprocessed. 后台 not recovered, lost ~ 50 messages in flight. Fix: <code>transactional outbox status</code> 的 flow diagram + worker 状态 mask 处理 commit-后 , 并让 update outbox <code>sent=true</code> 操作精确 reflect queue deliver ACK。</p><h3 id="outbox-grows-huge" tabindex="-1">Outbox grows huge <a class="header-anchor" href="#outbox-grows-huge" aria-label="Permalink to &quot;Outbox grows huge&quot;">​</a></h3><p>某用户 outbox retention 太长 (30 天保留) 导致 outbox 表数百 GB; worker 跟不上 batch send 量. Fix: outbox 在 row sent 后 brand job TTL preserve shorter,定期 cleanup 表 + 压 较 archive 表 之的政策.</p><h3 id="repeat-consume-duplication-in-kafka-消费者-未用-idempotency-key" tabindex="-1">Repeat consume duplication in Kafka 消费者 未用 idempotency key <a class="header-anchor" href="#repeat-consume-duplication-in-kafka-消费者-未用-idempotency-key" aria-label="Permalink to &quot;Repeat consume duplication in Kafka 消费者 未用 idempotency key&quot;">​</a></h3><p>消费 log 不 dedup 设置; duplicate events 导致 后端 subscribe 收到 500+ emails duplicated.</p><p>Fix: 客户端 insert idempotency unique key in row → INSERT ignored. Stripe webhook: <code>event_id</code> unique index防重复入.</p><h3 id="worker-处理过慢-outbox-饱和" tabindex="-1">Worker 处理过慢 outbox 饱和 <a class="header-anchor" href="#worker-处理过慢-outbox-饱和" aria-label="Permalink to &quot;Worker 处理过慢 outbox 饱和&quot;">​</a></h3><p>某公司 orders service high peak during 11.11 holiday, outbox worker 跟不上发 send rate → outbox rows accumulated → outbox 表 disk 满. Fix: worker 数量按 peak 5× capacity scaling + binlogs CDC 取代 poll-based.</p><h3 id="race-duplicate-enqueue" tabindex="-1">Race Duplicate Enqueue <a class="header-anchor" href="#race-duplicate-enqueue" aria-label="Permalink to &quot;Race Duplicate Enqueue&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">worker1.poll(): gets row </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">worker2.poll(): gets row </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # worker1 crash before SKIP LOCKED OR predates SKIP LOCKED patch</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">worker1 recovers → sends row </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">worker2 sends row </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # duplicate send</span></span></code></pre></div><p>Fix: SKIP LOCKED 是 required ALWAYS; worker 必有 <code>FOR UPDATE SKIP LOCKED</code> SQL clause.</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>worker 必须 idempotent</strong>: 不能简单发包; <code>event_id</code> 作为 idempotency key + queue dedup (e.g. <code>MessageDeduplicationId</code> 在 Amazon SQS)。</li><li><strong><code>FOR UPDATE SKIP LOCKED</code> 是 PostgreSQL 9.5+ / MySQL 8.0+ feature</strong>: 句不能在 older DB 上安全跑; 必使用 <code>SELECT ... LOCK IN SHARE MODE</code> 或 row-version 二次检查.</li><li><strong><code>SELECT FOR UPDATE SKIP LOCKED</code> 必 required</strong>: multiple workers 并发 unblocking concurrent 参数 set 跳避免 双 worker 处理同 row。</li><li><strong>Sent at / marked sent 不 atomic with outside queue send</strong>: queue send 后才 mark sent; 在未 mark sent 前 send 成功与 mark sent 之间 crash → 重发故 mark <code>sent=true</code> <strong>POST send ack</strong> 后立刻 <code>UPDATE</code>.</li><li><strong>Outbox 表保留 太长必爆炸</strong>: 实践 30天 archive 后 cleanup. 配置 retention 持续 monitor。</li><li><strong>Multi-partition 跨序业务</strong>: Kafka ordering 是单 partition; cross-partition 全序顺序 非 guarantee. 业务依赖全序必 single partition （限制 throughput).</li><li><strong>Use event_id作 partition key</strong>: 不要 user_id+timestamp 自乱 partition distribution partitioning 或 partition reliable。</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>Outbox Pattern 让 DB + queue <strong>transactionally atomic</strong> in single-service setup. CIIC 接受用 polling + worker + SKIP LOCKED pattern。</li><li>CDC (Debezium) trend: 流式 emit binlog → Kafka (低 latency, transactional robust, complexity).</li><li><strong><code>FOR UPDATE SKIP LOCKED</code></strong> 让 multi-worker concurrent polling 不冲突, PostgreSQL/MySQL/SQL Server 都支持。</li><li><strong>Idempotency Key on <code>event_id</code> 是必须的</strong>: 让 consumer idempotent dedup, queue <code>MessageDeduplicationId</code> 支持 AWS SQS FIFO, Kafka producer_id 提供应用层 dedup。</li><li>Kafka partitions + ordering: 同 entity events 同 partition 保序; cross-entity 不序需业务iidempotency。</li><li>典型工程: order service → shipping; user signup → email; tweet → fanout; payment → fraud——所有这些需要 outbox pattern 与 idempotency 保证 consistent + reliable fan-out 之服务架构 correctness.</li></ol><hr><p>下一节 → <a href="./kafka">Kafka 内部与生产实践</a></p>`,78)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
